from taf.ul.bts_kpi_report_generator.generator.Generate import GenerateHTML, GenerateXLSX, GenerateJSONCounters


class GenerateFiles(object):
    def __init__(self, path_dir, measurements, counters_name):
        """

        :param path_dir:
        :param measurements:
        :param counters_name:
        """
        self.__path_dir = path_dir
        self.__measurements = measurements
        self.__counters_name = counters_name

        self.__summary_measurement = None
        self.__summary_type_measurements = {}
        self.__summary_start_time = None
        self.__summary_interval = 0

    def generate(self):
        """

        :return:
        """
        self.__generate_summary()
        file_xlsx = GenerateXLSX(self.__path_dir, self.__measurements, self.__summary_measurement, self.__summary_type_measurements,
                                 self.__summary_start_time, self.__summary_interval, self.__counters_name)
        file_xlsx.generate()
        file_html = GenerateHTML(self.__path_dir, self.__measurements, self.__summary_measurement, self.__summary_type_measurements,
                                 self.__summary_start_time, self.__summary_interval, self.__counters_name)
        file_html.generate()
        file_json = GenerateJSONCounters(self.__path_dir, self.__measurements, self.__summary_measurement, self.__summary_type_measurements,
                                         self.__summary_start_time, self.__summary_interval, self.__counters_name)
        file_json.generate()

    def __generate_summary(self):
        """

        :return:
        """
        if len(self.__measurements) > 1:
            self.__summary_measurement = {}
            self.__summary_start_time = self.__measurements[sorted(self.__measurements)[0]].start_time

            for measurement in self.__measurements:
                self.__summary_interval = self.__summary_interval + int(self.__measurements[measurement].interval)
                for m_parameter in self.__measurements[measurement].parameters:
                    if m_parameter not in self.__summary_measurement:
                        self.__summary_measurement[m_parameter] = {}
                    self.__scan_dn(measurement, m_parameter)
                self.__scan_type_measurement(measurement)

    def __scan_dn(self, measurement, m_parameter):
        """

        :param measurement:
        :param m_parameter:
        :return:
        """
        for dn in self.__measurements[measurement].parameters[m_parameter]:
            if dn not in self.__summary_measurement[m_parameter]:
                self.__summary_measurement[m_parameter][dn] = 0
            self.__summary_measurement[m_parameter][dn] = self.__summary_measurement[m_parameter][dn] + float(
                self.__measurements[measurement].parameters[m_parameter][dn])

    def __scan_type_measurement(self, measurement):
        """

        :param measurement:
        :return:
        """
        for type_measurement in self.__measurements[measurement].type_measurements:
            if type_measurement not in self.__summary_type_measurements:
                self.__summary_type_measurements[type_measurement] = []
            for m_parameter in self.__measurements[measurement].type_measurements[type_measurement]:
                if m_parameter not in self.__summary_type_measurements[type_measurement]:
                    self.__summary_type_measurements[type_measurement].append(m_parameter)
